command:
$ErrorActionPreference = "Stop"

git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "591ecbad86a133812fa27521ca771aaba15e2ffe") { throw "main moved" }

if ((git status --short).Count -ne 0) { throw "persistent checkout is dirty" }
git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "fast-forward main failed" }

python -X utf8 -m unittest tests.winui.test_remote_windows_task_contract
if ($LASTEXITCODE -ne 0) { throw "remote control contract failed" }

git -C $env:GITHUB_WORKSPACE push origin --delete work/large-folder-5000 work/search-v2
if ($LASTEXITCODE -ne 0) { throw "work branch cleanup failed" }

Write-Host "REMOTE_CONTROL_POLICY_PASS"
Write-Host "WORK_BRANCH_CLEANUP_PASS"
